<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $listing_id
 * @property string $boost_package_id
 * @property string $user_id
 * @property string $status
 * @property int $amount
 * @property string $currency
 * @property Carbon|null $starts_at
 * @property Carbon|null $ends_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class ListingPromotion extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'lpr';

    protected $fillable = [
        'listing_id', 'boost_package_id', 'user_id', 'status', 'amount', 'currency', 'starts_at', 'ends_at',
    ];

    protected function casts(): array
    {
        return [
            'starts_at' => 'datetime',
            'ends_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Listing, $this> */
    public function listing(): BelongsTo
    {
        return $this->belongsTo(Listing::class);
    }

    /** @return BelongsTo<BoostPackage, $this> */
    public function package(): BelongsTo
    {
        return $this->belongsTo(BoostPackage::class, 'boost_package_id');
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    public function total(): Money
    {
        return Money::of($this->amount, $this->currency);
    }
}
